-- Query the database generated by: python -m src.main
-- sqlite3 outputs/exchange_rates.db < sql/analysis.sql

-- Latest PTAX selling rate per currency
SELECT r.currency, r.quote_date, ROUND(r.sell_rate, 4) AS sell_rate_brl
FROM exchange_rates r
WHERE r.quote_date = (SELECT MAX(r2.quote_date)
                      FROM exchange_rates r2 WHERE r2.currency = r.currency)
ORDER BY r.currency;

-- Monthly average by currency
SELECT currency, SUBSTR(quote_date, 1, 7) AS month,
       ROUND(AVG(sell_rate), 4) AS avg_sell_rate
FROM exchange_rates GROUP BY currency, month ORDER BY month, currency;

-- Minimum and maximum rates in stored period
SELECT currency, MIN(sell_rate) AS minimum, MAX(sell_rate) AS maximum
FROM exchange_rates GROUP BY currency;

-- Day-on-day percentage variation (between observed business days)
SELECT currency, quote_date, ROUND(sell_rate, 4) AS sell_rate,
       ROUND(100.0 * (sell_rate / LAG(sell_rate)
            OVER (PARTITION BY currency ORDER BY quote_date) - 1), 3) AS change_pct
FROM exchange_rates ORDER BY currency, quote_date;
